function dimBar(g, m1, m2, y, txt, color, mode, tip, ttl, body) {
  var xa = PX(m1), xb = PX(m2);
  var w = (mode === 'ref') ? 1.1 : (mode === 'hl' ? 1.9 : 1.7);
  var tick = (mode === 'ref') ? 8 : 9.5;
  g.line(xa, y - tick, xa, y + tick).stroke({ color: color, width: w });
  g.line(xb, y - tick, xb, y + tick).stroke({ color: color, width: w });
  var mid = (xa + xb) / 2;
  if (xb - xa > 30) {
    arrowLine(g, mid, y, xa + 1, y, color, w, 8);
    arrowLine(g, mid, y, xb - 1, y, color, w, 8);
  } else {
    g.line(xa, y, xb, y).stroke({ color: color, width: w });
  }
  var lx = mid, anchor = 'middle';
  if (xb - xa < 100) { lx = xb + 9; anchor = 'start'; }
  label(g, txt, lx, y, 12, color, anchor, SERIF, true, 4);
  if (tip) {
    var h = g.rect(Math.max(14, xb - xa), 22).move(xa, y - 11).fill('#000').opacity(0);
    interactive(h, tip, ttl, body);
