      'Your launch: ' + v + ' m/s at ' + th + '°  →  ' + txt,
      'Your range bar',
      'This bar appears only while your settings differ from the three textbook launches; ' +
      'when they coincide, the matching printed bar is simply drawn bolder instead.');
  }
}

/* ---------- render ---------- */
function render() {
  computeScale();
  root.clear();
  var hl = activeMatch();
  drawPanelA(st.panel === 'a' ? hl : -1);
  drawPanelB(st.panel === 'b' ? hl : -1);
  drawActive(hl);
  updateReadout();
}

function updateReadout() {
  var v = st.v, th = st.ang;
  var R = rangeOf(v, th), A = apexOf(v, th), T = tofOf(v, th);
  var s = 'R = v₀²·sin(2θ)/g<br>' +
    'v₀ = ' + v.toFixed(0) + ' m/s   θ = ' + th.toFixed(0) + '°<br>' +
    'sin(2θ) = ' + Math.sin(2 * th * Math.PI / 180).toFixed(3) + '<br>' +
    '<b>R = ' + R.toFixed(1) + ' m</b><br>' +
    'h_max = ' + A.toFixed(1) + ' m   t = ' + T.toFixed(2) + ' s';
  if (st.comp && Math.abs(90 - 2 * th) > 1) {
    var th2 = 90 - th;
    s += '<br>90°−θ = ' + th2.toFixed(0) + '° → R = ' + rangeOf(v, th2).toFixed(1) +
      ' m, h_max = ' + apexOf(v, th2).toFixed(1) + ' m';
  }
  document.getElementById('readout').innerHTML = s;
}

/* ---------- UI sync ---------- */
function syncInputs() {
  var sp = document.getElementById('initialSpeedInput'), an = document.getElementById('launchAngleInput');
  sp.value = st.v; document.getElementById('initialSpeedVal').value = st.v;
  an.value = st.ang; document.getElementById('launchAngleVal').value = st.ang;
  document.getElementById('showComplementInput').checked = st.comp;
  document.getElementById('panelViewInput').value = st.panel;
  sp.disabled = (st.panel !== 'a');
  an.disabled = (st.panel !== 'b');
  document.getElementById('speedLab').style.opacity = sp.disabled ? '0.45' : '1';
  document.getElementById('angleLab').style.opacity = an.disabled ? '0.45' : '1';
}

function update_initialSpeed(v) { st.v = v; render(); }
function update_launchAngle(a) { st.ang = a; render(); }
function toggle_showComplement(on) { st.comp = !!on; render(); }
function toggle_panelView(p) {
  st.panel = (p === 'b') ? 'b' : 'a';
  if (st.panel === 'a') { st.ang = 45; } else { st.v = 50; }
  syncInputs(); render();
}

/* ---------- demo steps ---------- */
var steps = [
  { t: 'One launch, one parabola', n: 'A projectile leaves the origin at 30 m/s and 45° and returns to the same ground line 91.8 m away. The dashed line marks its apex; the first bar below measures its range.', s: { p: 'a', v: 30, a: 45, c: false } },
  { t: 'More speed, much more range', n: 'Raise v₀ to 40 m/s: the angle is unchanged, but the range jumps to 163 m — far more than the 33% speed increase would suggest.', s: { p: 'a', v: 40, a: 45, c: false } },
  { t: 'Range scales as v₀²', n: 'At 50 m/s the projectile reaches 255 m. Comparing 30, 40 and 50 m/s shows the ranges scale like 9 : 16 : 25 — exactly the squares of the speeds.', s: { p: 'a', v: 50, a: 45, c: false } },
  { t: 'Now hold speed, sweep the angle', n: 'Switch to panel (b): v₀ is locked at 50 m/s. A shallow 15° launch gives a flat arc that lands at 128 m.', s: { p: 'b', v: 50, a: 15, c: false } },
  { t: '45° maximizes the range', n: 'Drag θ upward: the range grows to a maximum of 255 m at 45°, then falls again as the arc becomes steep and tall.', s: { p: 'b', v: 50, a: 45, c: false } },
  { t: 'Complementary angles share a landing point', n: 'At 75° the projectile climbs much higher and hangs much longer, yet it lands at the very same 128 m as the 15° shot — complementary angles give equal range.', s: { p: 'b', v: 50, a: 75, c: true } }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i + steps.length) % steps.length;
  var s = steps[curStep].s;
  st.panel = s.p; st.v = s.v; st.ang = s.a; st.comp = s.c;
  syncInputs();
  render();
  document.getElementById('demoNarration').innerHTML =
    '<b>' + steps[curStep].t + '</b><br>' + steps[curStep].n;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

