Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0 0 2px 0;font-size:11.5px;line-height:1.5;color:#1a1a1a"></p>
<span style="display:flex;align-items:center;gap:8px"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:11px;color:#444"></span><button onclick="nextStep()">▶</button></span>
<label>Panel
  <select id="panelViewInput" onchange="toggle_panelView(this.value)">
    <option value="a">(a) vary speed, θ = 45°</option>
    <option value="b">(b) vary angle, v₀ = 50 m/s</option>
  </select>
</label>
<label id="speedLab">Initial speed v₀ (m/s): <output id="initialSpeedVal">30</output><input id="initialSpeedInput" type="range" min="10" max="60" step="1" value="30" oninput="document.getElementById('initialSpeedVal').value=this.value;update_initialSpeed(+this.value)"></label>
<label id="angleLab">Launch angle θ (degrees): <output id="launchAngleVal">45</output><input id="launchAngleInput" type="range" min="5" max="85" step="1" value="45" oninput="document.getElementById('launchAngleVal').value=this.value;update_launchAngle(+this.value)"></label>
<label><input id="showComplementInput" type="checkbox" onchange="toggle_showComplement(this.checked)"> Show complementary angle (90° − θ)</label>
<p id="readout" style="margin:2px 0 0 0;font:11px/1.6 ui-monospace,Consolas,monospace;color:#111;background:#f1f3f5;border:1px solid #dcdfe3;border-radius:4px;padding:6px 8px"></p>
<p style="margin:0;font-size:10px;line-height:1.45;color:#555">Both sliders stay live in either panel: the printed 30/40/50 m/s and 15°/45°/75° launches remain as reference curves, and your own launch is drawn bolder whenever it differs from them. Hover a curve, arrow or range bar for details; click for an explanation.</p>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 560, FH = 680;
draw.viewbox(0, 0, FW, FH).attr('preserveAspectRatio', 'xMidYMid meet');

var G = 9.8;
var C_O = '#e8602c', C_P = '#96269b', C_T = '#189a97', C_K = '#1a1a1a', C_D = '#9aa0a6';
var X0 = 52, SPAN = 478, BASE_NEED = 290;
var SX = SPAN / BASE_NEED, SY = 0.85 * SX;
var YA = 190, YB = 545;
var BARS_A = [226, 252, 278], BARS_B = [581, 607];
var ACT_BAR = { a: 304, b: 633 };
var CAP_A = 332, CAP_B = 662;
var SERIF = 'Georgia, "Times New Roman", serif';
var FS_BAR = 15, FS_SPD = 14, FS_ANG = 13, FS_CAP = 16, FS_KEY = 15;

var root = draw.group();
var st = { panel: 'a', v: 30, ang: 45, comp: false };

/* ---------- physics ---------- */
function rangeOf(v, th) { return v * v * Math.sin(2 * th * Math.PI / 180) / G; }
function apexOf(v, th) { var s = Math.sin(th * Math.PI / 180); return v * v * s * s / (2 * G); }
function tofOf(v, th) { return 2 * v * Math.sin(th * Math.PI / 180) / G; }
function hAt(v, th, x) {
  var rad = th * Math.PI / 180, R = rangeOf(v, th);
  return x * Math.tan(rad) * (1 - x / R);
}

/* ---------- mapping ---------- */
function PX(m) { return X0 + m * SX; }
function PY(h, gy) { return gy - h * SY; }

function computeScale() {
  var R = rangeOf(st.v, st.ang);
  var need = Math.max(BASE_NEED, R * 1.06);
  SX = SPAN / need;
  SY = 0.85 * SX;
  var room = (st.panel === 'a') ? (YA - 25) : (YB - 345);
  var hNeed = apexOf(st.v, st.ang);
  if (st.comp) hNeed = Math.max(hNeed, apexOf(st.v, 90 - st.ang));
  if (hNeed * SY > room) SY = room / hNeed;
}

/* ---------- drawing helpers ---------- */
function label(g, str, x, y, size, color, anchor, italic, halo) {
  var t = g.plain(str);
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'middle',
    'font-family': SERIF, 'font-size': size, 'font-style': italic ? 'italic' : 'normal',
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': (halo == null ? 3.4 : halo),
    'stroke-linejoin': 'round', 'pointer-events': 'none'
  });
  t.fill(color || C_K);
  return t;
}

function arrowLine(g, x1, y1, x2, y2, color, w, hl) {
  hl = hl || 9;
  var a = Math.atan2(y2 - y1, x2 - x1), hw = hl * 0.42;
  var bx = x2 - hl * Math.cos(a), by = y2 - hl * Math.sin(a);
  var px = -Math.sin(a), py = Math.cos(a);
  g.line(x1, y1, bx, by).stroke({ color: color, width: w, linecap: 'round' });
  g.polygon([[x2, y2], [bx + hw * px, by + hw * py], [bx - hw * px, by - hw * py]]).fill(color);
}

function arcPath(g, r, deg, gy, color, w) {
  var rad = deg * Math.PI / 180;
  var d = 'M' + (X0 + r) + ' ' + gy + ' A' + r + ' ' + r + ' 0 0 0 ' +
    (X0 + r * Math.cos(rad)).toFixed(2) + ' ' + (gy - r * Math.sin(rad)).toFixed(2);
  g.path(d).fill('none').stroke({ color: color || '#333', width: w || 1 });
}

function trajPoints(v, th, gy) {
  var rad = th * Math.PI / 180, R = rangeOf(v, th), n = 130, pts = [];
  var tn = Math.tan(rad), k = G / (2 * v * v * Math.cos(rad) * Math.cos(rad));
  for (var i = 0; i <= n; i++) {
    var x = R * i / n, h = x * tn - k * x * x;
    if (h < 0) h = 0;
    pts.push([PX(x), PY(h, gy)]);
  }
  return pts;
}
function toPath(pts) {
  var d = '';
  for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(2) + ' ' + pts[i][1].toFixed(2);
  return d;
}

function interactive(el, tip, ttl, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(ttl, body); });
  return el;
}

function curve(g, v, th, gy, color, w, dashed, tip, ttl, body) {
  var d = toPath(trajPoints(v, th, gy));
  var hit = g.path(d).fill('none').stroke({ color: '#000', width: 13, opacity: 0 });
  var p = g.path(d).fill('none').stroke({ color: color, width: w, linecap: 'round', linejoin: 'round' });
  if (dashed) p.attr('stroke-dasharray', '7,5');
  if (tip) interactive(hit, tip, ttl, body);
  return p;
}

function hitLine(g, x1, y1, x2, y2, tip, ttl, body) {
  var h = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 14, opacity: 0, linecap: 'round' });
  interactive(h, tip, ttl, body);
}

/* mode: 'ref' (thin black, as printed) | 'hl' (printed bar matching the learner's
   current launch) | 'act' (the learner's own, genuinely new range)            */
function dimBar(g, m1, m2, y, txt, color, mode, tip, ttl, body) {
  var xa = PX(m1), xb = PX(m2);
  var w = (mode === 'ref') ? 1.2 : (mode === 'hl' ? 2.0 : 1.8);
  var tick = 9.5;
  g.line(xa, y - tick, xa, y + tick).stroke({ color: color, width: w });
  g.line(xb, y - tick, xb, y + tick).stroke({ color: color, width: w });
  var mid = (xa + xb) / 2, tw = txt.length * FS_BAR * 0.5;
  if (xb - xa > tw + 46) {
    arrowLine(g, mid - tw / 2 - 8, y, xa + 1, y, color, w, 9);
    arrowLine(g, mid + tw / 2 + 8, y, xb - 1, y, color, w, 9);
    label(g, txt, mid, y, FS_BAR, color, 'middle', true, 3);
  } else {
    g.line(xa, y, xb, y).stroke({ color: color, width: w });
    label(g, txt, xb + 11, y, FS_BAR, color, 'start', true, 3);
  }
  if (tip) {
    var h = g.rect(Math.max(16, xb - xa), 24).move(xa, y - 12).fill('#000').opacity(0);
    interactive(h, tip, ttl, body);
  }
}

/* which printed range bar (if any) the learner's settings coincide with */
function activeMatch() {
  if (st.panel === 'a') {
    if (st.ang === 45) { var i = [30, 40, 50].indexOf(st.v); if (i >= 0) return i; }
  } else if (st.v === 50) {
    if (st.ang === 15 || st.ang === 75) return 0;
    if (st.ang === 45) return 1;
  }
  return -1;
}

/* ---------- panel (a): 45° launch, three speeds ---------- */
function drawPanelA(hl) {
  var g = root.group(), gy = YA;
  var refs = [{ v: 30, c: C_O }, { v: 40, c: C_P }, { v: 50, c: C_T }];

  /* printed dashed apex guides: only the 40 and 50 m/s curves carry them */
  [40, 50].forEach(function (v) {
    var R = rangeOf(v, 45), A = apexOf(v, 45);
    g.line(PX(R / 2), PY(A, gy), PX(R / 2), gy).stroke({ color: C_D, width: 1, dasharray: '5,4' });
  });
  g.line(X0 - 4, gy, FW - 20, gy).stroke({ color: '#333', width: 1.3 });

  refs.forEach(function (r) {
    var R = rangeOf(r.v, 45);
    curve(g, r.v, 45, gy, r.c, 1.9, false,
      r.v + ' m/s at 45°  →  R = ' + R.toFixed(1) + ' m',
      'Fixed angle, changing speed',
      'Launched at 45° with v₀ = ' + r.v + ' m/s the projectile lands ' + R.toFixed(1) + ' m away. ' +
      'Since R = v₀² sin(2θ)/g and sin 90° = 1, the range here is simply v₀²/g. ' +
      'The three ranges 91.8, 163 and 255 m stand in the ratio 9 : 16 : 25 — the squares of 30, 40 and 50.');
  });

  refs.forEach(function (r) {
    var L = 52 + (r.v - 30) * 3, c = Math.SQRT1_2;
    var tx = X0 + L * c, ty = gy - L * c;
    arrowLine(g, X0, gy, tx, ty, r.c, 2.2, 10);
    hitLine(g, X0, gy, tx, ty, 'Launch velocity ' + r.v + ' m/s at 45°',
      'Initial velocity vector',
      'Every arrow here points at 45°; only its length (the launch speed) changes. ' +
      'The horizontal and vertical components are equal, v₀/√2 = ' + (r.v / Math.SQRT2).toFixed(1) + ' m/s each.');
    label(g, r.v + ' m/s', tx - 17, ty - 13, FS_SPD, C_K, 'end', false);
  });

  arcPath(g, 48, 45, gy, '#333', 1);
  label(g, '45°', X0 + 92, gy - 16, FS_ANG, C_K, 'middle', false, 3.2);

  [[30, 'R = 91.8 m'], [40, 'R = 163 m'], [50, 'R = 255 m']].forEach(function (b, i) {
    var R = rangeOf(b[0], 45), on = (hl === i);
    dimBar(g, 0, R, BARS_A[i], b[1], C_K, on ? 'hl' : 'ref',
      b[1] + (on ? '  (your current launch)' : '  — 45° launch at ' + b[0] + ' m/s'),
      'Horizontal range', 'R = v₀²/g at 45°: (' + b[0] + ' m/s)² / 9.8 = ' + R.toFixed(1) + ' m. ' +
      'The bar ends exactly under the landing point of the matching curve.');
  });

  /* axis key */
  arrowLine(g, 500, 72, 500, 24, C_K, 1.7, 9);
  arrowLine(g, 500, 72, 542, 72, C_K, 1.7, 9);
  label(g, 'y', 490, 30, FS_KEY, C_K, 'end', true).attr('font-weight', '700');
  label(g, 'x', 546, 80, FS_KEY, C_K, 'start', true).attr('font-weight', '700');
  label(g, '(a)', FW / 2, CAP_A, FS_CAP, C_K, 'middle', true);
}

/* ---------- panel (b): 50 m/s, three angles ---------- */
function drawPanelB(hl) {
  var g = root.group(), gy = YB;
  var refs = [{ a: 15, c: C_O }, { a: 45, c: C_P }, { a: 75, c: C_T }];

  var R75 = rangeOf(50, 75), A75 = apexOf(50, 75);
  g.line(PX(R75 / 2), PY(A75, gy), PX(R75 / 2), gy).stroke({ color: C_D, width: 1, dasharray: '5,4' });
  var R15 = rangeOf(50, 15);
  g.line(PX(R15), PY(hAt(50, 45, R15), gy), PX(R15), gy).stroke({ color: C_D, width: 1, dasharray: '5,4' });
  g.line(X0 - 4, gy, FW - 20, gy).stroke({ color: '#333', width: 1.3 });

  refs.forEach(function (r) {
    var R = rangeOf(50, r.a);
    curve(g, 50, r.a, gy, r.c, 1.9, false,
      '50 m/s at ' + r.a + '°  →  R = ' + R.toFixed(1) + ' m',
      'Fixed speed, changing angle',
      'At v₀ = 50 m/s the range is R = (2500/9.8)·sin 2θ. For θ = ' + r.a + '°, sin 2θ = ' +
      Math.sin(2 * r.a * Math.PI / 180).toFixed(3) + ', giving R = ' + R.toFixed(1) + ' m. ' +
      'The 15° and 75° shots share the same sin 2θ, so they land together even though the 75° arc is far taller and slower.');
  });

  var LEN = { 15: 76, 45: 105, 75: 128 };
  refs.forEach(function (r) {
    var rad = r.a * Math.PI / 180, L = LEN[r.a];
    var tx = X0 + L * Math.cos(rad), ty = gy - L * Math.sin(rad);
    arrowLine(g, X0, gy, tx, ty, r.c, 2.2, 10);
    hitLine(g, X0, gy, tx, ty, 'Launch velocity 50 m/s at ' + r.a + '°',
      'Initial velocity vector',
      'All three arrows have the same speed, 50 m/s; only the direction changes. ' +
      'Vertical component v₀sinθ = ' + (50 * Math.sin(rad)).toFixed(1) + ' m/s sets the height and hang time, ' +
      'horizontal component v₀cosθ = ' + (50 * Math.cos(rad)).toFixed(1) + ' m/s sets how fast it travels downrange.');
  });

  arcPath(g, 58, 15, gy, '#333', 1);
  arcPath(g, 82, 45, gy, '#333', 1);
  arcPath(g, 104, 75, gy, '#333', 1);

  /* angle labels moved into open space; the shallow 15° wedge gets a short leader */
  g.line(190, gy - 26, 112, gy - 12).stroke({ color: '#8a8f94', width: 0.8 });
  label(g, '15°', 202, gy - 30, FS_ANG, C_K, 'middle', false, 3.2);
  label(g, '45°', 137, gy - 43, FS_ANG, C_K, 'middle', false, 3.2);
  label(g, '75°', 117, gy - 101, FS_ANG, C_K, 'middle', false, 3.2);
  label(g, 'v₀ = 50 m/s', 8, gy - 142, FS_KEY, C_K, 'start', true);

  [[R15, 'R = 128 m', '15° and 75°'], [rangeOf(50, 45), 'R = 255 m', '45°']].forEach(function (b, i) {
    var on = (hl === i);
    dimBar(g, 0, b[0], BARS_B[i], b[1], C_K, on ? 'hl' : 'ref',
      b[1] + (on ? '  (your current launch)' : '  — ' + b[2] + ' at 50 m/s'),
      'Horizontal range',
      'R = (2500/9.8)·sin 2θ = ' + b[0].toFixed(1) + ' m for ' + b[2] + '. ' +
      'Because sin 2θ = sin(180° − 2θ), the 15° and 75° launches share one bar; 45° gives the longest bar of all.');
  });

  label(g, '(b)', FW / 2, CAP_B, FS_CAP, C_K, 'middle', true);
}

function activeColor() {
  if (st.panel === 'a') return st.v < 35 ? C_O : (st.v < 45 ? C_P : C_T);
  return st.ang < 30 ? C_O : (st.ang < 60 ? C_P : C_T);
}

/* ---------- learner-controlled trajectory ---------- */
function drawActive(hl) {
  var g = root.group();
  var gy = st.panel === 'a' ? YA : YB;
  var v = st.v, th = st.ang, col = activeColor(), matched = (hl >= 0);
  var R = rangeOf(v, th), A = apexOf(v, th), T = tofOf(v, th);

  if (st.comp && Math.abs(90 - 2 * th) > 1) {
    var th2 = 90 - th, A2 = apexOf(v, th2);
    g.line(PX(R / 2), PY(A2, gy), PX(R / 2), gy).stroke({ color: col, width: 1, dasharray: '3,3', opacity: 0.5 });
    curve(g, v, th2, gy, col, 2.2, true,
      'Complement ' + th2.toFixed(0) + '°  →  R = ' + rangeOf(v, th2).toFixed(1) + ' m (same landing point)',
      'Complementary angles',
      'θ = ' + th.toFixed(0) + '° and 90° − θ = ' + th2.toFixed(0) + '° give the same sin 2θ, hence exactly the same range. ' +
      'The steeper shot climbs higher (' + A2.toFixed(1) + ' m vs ' + A.toFixed(1) + ' m) and stays airborne longer (' +
      tofOf(v, th2).toFixed(2) + ' s vs ' + T.toFixed(2) + ' s), trading height for horizontal speed.');
  }

  if (!matched) {
    g.line(PX(R / 2), PY(A, gy), PX(R / 2), gy).stroke({ color: col, width: 1.1, dasharray: '5,4', opacity: 0.8 });
  }

  curve(g, v, th, gy, col, matched ? 2.4 : 3.0, false,
    'Active: ' + v + ' m/s at ' + th + '°  →  R = ' + R.toFixed(1) + ' m',
    'The active trajectory',
    'R = v₀² sin 2θ / g = (' + v + '² × ' + Math.sin(2 * th * Math.PI / 180).toFixed(3) + ') / 9.8 = ' + R.toFixed(1) + ' m. ' +
    'Apex height v₀²sin²θ/(2g) = ' + A.toFixed(1) + ' m and flight time 2v₀sinθ/g = ' + T.toFixed(2) + ' s. ' +
    'Speed enters squared, so it dominates; the angle enters only through sin 2θ.');

  if (!matched) {
    var dot = g.circle(7).center(PX(R), gy).fill(col);
    interactive(dot, 'Lands at ' + R.toFixed(1) + ' m after ' + T.toFixed(2) + ' s', 'Landing point',
      'The projectile returns to launch height after ' + T.toFixed(2) + ' s, ' + R.toFixed(1) +
      ' m downrange. It sits exactly above the end tick of its range bar.');

    var txt = 'R = ' + (R >= 100 ? R.toFixed(0) : R.toFixed(1)) + ' m';
    dimBar(g, 0, R, ACT_BAR[st.panel], txt, col, 'act',
      'Your launch: ' + v + ' m/s at ' + th + '°  →  ' + txt,
      'Your range bar',
      'This extra bar appears only while your settings differ from the printed launches; ' +
      'when they coincide, the matching printed bar is simply drawn bolder instead.');
  }
}

/* ---------- render ---------- */
function render() {
  computeScale();
  root.clear();
  var hl = activeMatch();
  drawPanelA(st.panel === 'a' ? hl : -1);
  drawPanelB(st.panel === 'b' ? hl : -1);
  drawActive(hl);
